-- | A graph under construction. Its builders (`matmul`, `conv2d`, …) are the op
-- table's (`table.rs`); these rows are its lifecycle.
newtype Graph = Graph (ForeignPtr ())

instance Handle Graph where
  handlePtr (Graph p) = p

-- | A graph split into self-contained parts that run in order: part i reads
-- its `imports` from earlier parts' `exports` of the same name.
newtype Partition = Partition (ForeignPtr ())

instance Handle Partition where
  handlePtr (Partition p) = p

-- | A device and precision to compile graphs for.
newtype Session = Session (ForeignPtr ())

instance Handle Session where
  handlePtr (Session p) = p

-- | A session that picks the device per graph, by policy.
newtype FlexibleSession = FlexibleSession (ForeignPtr ())

instance Handle FlexibleSession where
  handlePtr (FlexibleSession p) = p

-- | A graph compiled for one device.
newtype Compiled = Compiled (ForeignPtr ())

instance Handle Compiled where
  handlePtr (Compiled p) = p

-- | One graph compiled for every device a policy allows, for benchmarking and picking.
newtype Runner = Runner (ForeignPtr ())

instance Handle Runner where
  handlePtr (Runner p) = p

-- | Routes each run to a device by policy, benchmarking and falling back.
newtype Router = Router (ForeignPtr ())

instance Handle Router where
  handlePtr (Router p) = p

-- | A GGUF file opened for reading.
newtype Gguf = Gguf (ForeignPtr ())

instance Handle Gguf where
  handlePtr (Gguf p) = p

-- | Builds a GGUF file tensor by tensor.
newtype GgufWriter = GgufWriter (ForeignPtr ())

instance Handle GgufWriter where
  handlePtr (GgufWriter p) = p

-- | An optimizer over named host tensors (Adam, AdamW, SGD, Muon, SOAP, …).
newtype Optimizer = Optimizer (ForeignPtr ())

instance Handle Optimizer where
  handlePtr (Optimizer p) = p

-- | Trains a graph's parameters: forward, backward, optimizer, on one device.
newtype Trainer = Trainer (ForeignPtr ())

instance Handle Trainer where
  handlePtr (Trainer p) = p

-- | A tokenizer.json tokenizer.
newtype Tokenizer = Tokenizer (ForeignPtr ())

instance Handle Tokenizer where
  handlePtr (Tokenizer p) = p

-- | A seeded sampler that keeps its own history.
newtype Sampler = Sampler (ForeignPtr ())

instance Handle Sampler where
  handlePtr (Sampler p) = p

-- | This process's place in a mesh of rlx nodes: point-to-point messages,
-- collectives, and the ship-graph protocol (a coordinator ships a stage or a
-- training job; generic workers run it on their own hardware).
newtype Group = Group (ForeignPtr ())

instance Handle Group where
  handlePtr (Group p) = p

-- | A model from any provider — an .rlxp package, a plugin's family runner
-- (LLMs, speech, vision, …) — opened by path or id and run by name.
newtype Model = Model (ForeignPtr ())

instance Handle Model where
  handlePtr (Model p) = p

-- | The library version, e.g. "0.2.18".
version :: IO String
version  =
  c_rlx_version  P.>>= peekCString

-- | Backends compiled in and usable on this machine.
devices :: IO [String]
devices  =
  allocaOut $ \o0 ->
  do
    checkRc P.=<< c_rlx_devices o0
    takeJsonAs o0

-- | Whether a backend is compiled in and has hardware.
isAvailable :: String -> IO Bool
isAvailable name =
  withStr name $ \a0 ->
  P.fmap toBool (c_rlx_is_available a0)

-- | The canonical label of a device name; errors on an unknown one.
parseDevice :: String -> IO String
parseDevice name =
  withStr name $ \a0 ->
  allocaOut $ \o0 ->
  do
    checkRc P.=<< c_rlx_parse_device a0 o0
    takeString o0

-- | Every backend rlx knows, with whether this build and machine have it.
backendsManifest :: IO Value
backendsManifest  =
  allocaOut $ \o0 ->
  do
    checkRc P.=<< c_rlx_backends_manifest o0
    takeJson o0

