-- | The optional parameters of 'check'; 'defCheck' holds the defaults.
data CheckOpts = CheckOpts
  { checkOptions :: Maybe Value
  }

defCheck :: CheckOpts
defCheck = CheckOpts
  { checkOptions = Nothing
  }

-- | Static analysis of `graph` across backends: unsupported ops, numerics, cost.
check :: Graph -> IO Value
check = checkWith defCheck

-- | 'check' with explicit optional parameters.
checkWith :: CheckOpts -> Graph -> IO Value
checkWith opts' graph =
  withH graph $ \a0 ->
  withJson (checkOptions opts') $ \a1 ->
  allocaOut $ \o0 ->
  do
    checkRc P.=<< c_rlx_check a0 a1 o0
    takeJson o0

-- | The backends `check` can analyse.
checkBackends :: IO [String]
checkBackends  =
  allocaOut $ \o0 ->
  do
    checkRc P.=<< c_rlx_check_backends o0
    takeJsonAs o0

-- | A graph whose outputs are [loss, …d(loss)/d(wrt)], with a `d_output` seed input.
grad :: Graph -> [Node] -> IO Graph
grad graph wrt =
  withH graph $ \a0 ->
  withU32s wrt $ \a1 ->
  allocaOut $ \o0 ->
  do
    checkRc P.=<< c_rlx_grad a0 a1 (P.fromIntegral (P.length wrt)) o0
    adopt Graph pFree_graph o0

-- | Forward mode: [...primals, ...tangents], one `tangent_<name>` input per seeded node.
jvp :: Graph -> [Node] -> IO Graph
jvp graph tangentFor =
  withH graph $ \a0 ->
  withU32s tangentFor $ \a1 ->
  allocaOut $ \o0 ->
  do
    checkRc P.=<< c_rlx_jvp a0 a1 (P.fromIntegral (P.length tangentFor)) o0
    adopt Graph pFree_graph o0

-- | Hessian-vector product, forward-over-reverse.
hvp :: Graph -> [Node] -> IO Graph
hvp graph wrt =
  withH graph $ \a0 ->
  withU32s wrt $ \a1 ->
  allocaOut $ \o0 ->
  do
    checkRc P.=<< c_rlx_hvp a0 a1 (P.fromIntegral (P.length wrt)) o0
    adopt Graph pFree_graph o0

-- | Batch the named inputs along a new leading axis.
vmap :: Graph -> [String] -> Int -> IO Graph
vmap graph names batchSize =
  withH graph $ \a0 ->
  withStrs names $ \a1 ->
  allocaOut $ \o0 ->
  do
    checkRc P.=<< c_rlx_vmap a0 a1 (P.fromIntegral (P.length names)) (P.fromIntegral batchSize) o0
    adopt Graph pFree_graph o0

-- | The order-th derivative of a scalar function w.r.t. scalar input `wrt`.
nthOrderGrad :: Graph -> String -> Int -> IO Graph
nthOrderGrad graph wrt order =
  withH graph $ \a0 ->
  withStr wrt $ \a1 ->
  allocaOut $ \o0 ->
  do
    checkRc P.=<< c_rlx_nth_order_grad a0 a1 (P.fromIntegral order) o0
    adopt Graph pFree_graph o0

-- | The order-th derivative contracted against one direction per level (`dir_0`, …).
directionalNthGrad :: Graph -> String -> Int -> IO Graph
directionalNthGrad graph wrt order =
  withH graph $ \a0 ->
  withStr wrt $ \a1 ->
  allocaOut $ \o0 ->
  do
    checkRc P.=<< c_rlx_directional_nth_grad a0 a1 (P.fromIntegral order) o0
