-- | A deep copy — compile one, keep building on the other.
clone :: Graph -> IO Graph
clone self' =
  withH self' $ \a0 ->
  allocaOut $ \o0 ->
  do
    checkRc P.=<< c_rlx_graph_clone a0 o0
    adopt Graph pFree_graph o0

-- | Whether a compile (or a body-graph argument) consumed it.
isConsumed :: Graph -> IO Bool
isConsumed self' =
  withH self' $ \a0 ->
  P.fmap toBool (c_rlx_graph_is_consumed a0)

-- | The optional parameters of 'splice'; 'defSplice' holds the defaults.
data SpliceOpts = SpliceOpts
  { spliceOptions :: Maybe Value
  }

defSplice :: SpliceOpts
defSplice = SpliceOpts
  { spliceOptions = Nothing
  }

-- | Copy `source` into `target` (both borrowed; `target` grows) and return
-- `source`'s outputs as `target` nodes. options: {bind: {leaf name: node},
-- prefix, adapt_shapes}. Unbound same-named leaves are shared (a tied weight)
-- unless `prefix` keeps them apart. On error `target` is unchanged.
splice :: Graph -> Graph -> IO [Node]
splice = spliceWith defSplice

-- | 'splice' with explicit optional parameters.
spliceWith :: SpliceOpts -> Graph -> Graph -> IO [Node]
spliceWith opts' target source =
  withH target $ \a0 ->
  withH source $ \a1 ->
  withJson (spliceOptions opts') $ \a2 ->
  allocaSlice $ \o0 ->
  do
    checkRc P.=<< c_rlx_splice a0 a1 a2 o0
    takeU32s o0

