  { parallelName :: Maybe String
  }

defParallel :: ParallelOpts
defParallel = ParallelOpts
  { parallelName = Nothing
  }

-- | `a` and `b` side by side: a's outputs, then b's; same-named leaves shared.
parallel :: Graph -> Graph -> IO Graph
parallel = parallelWith defParallel

-- | 'parallel' with explicit optional parameters.
parallelWith :: ParallelOpts -> Graph -> Graph -> IO Graph
parallelWith opts' a b =
  withH a $ \a0 ->
  withH b $ \a1 ->
  withStrMaybe (parallelName opts') $ \a2 ->
  allocaOut $ \o0 ->
  do
    checkRc P.=<< c_rlx_parallel a0 a1 a2 o0
    adopt Graph pFree_graph o0

