  withH graph $ \a0 ->
  withU32s assign $ \a1 ->
  allocaOut $ \o0 ->
  do
    checkRc P.=<< c_rlx_partition_new a0 a1 (P.fromIntegral (P.length assign)) o0
    adopt Partition pFree_partition o0

