  { scanXs = []
  , scanBcasts = []
  , scanCheckpoints = 0
  , scanTrajectory = False
  }

-- | `scan(init, body, length)`. `body`'s inputs are, in creation order,
-- the carry, each broadcast, then each per-step slice of `xs`; its one
-- output is the next carry. The body graph is **consumed**.
-- `trajectory` returns every carry stacked (`[length, …init]`).
scan :: Graph -> Node -> Graph -> Node -> IO Node
scan = scanWith defScan

-- | 'scan' with explicit optional parameters.
scanWith :: ScanOpts -> Graph -> Node -> Graph -> Node -> IO Node
scanWith opts' self' init body length =
  withH self' $ \a0 ->
  withH body $ \a2 ->
  withU32s (scanXs opts') $ \a4 ->
  withU32s (scanBcasts opts') $ \a5 ->
  allocaOut $ \o0 ->
  do
    checkRc P.=<< c_rlx_graph_scan a0 init a2 length a4 (P.fromIntegral (P.length (scanXs opts'))) a5 (P.fromIntegral (P.length (scanBcasts opts'))) (scanCheckpoints opts') (fromBool (scanTrajectory opts')) o0
    peekU32 o0

