-- | The optional parameters of 'spdBatchNorm'; 'defSpdBatchNorm' holds the defaults.
data SpdBatchNormOpts = SpdBatchNormOpts
  { spdBatchNormIters :: Node
  , spdBatchNormTol :: Float
  }

defSpdBatchNorm :: SpdBatchNormOpts
defSpdBatchNorm = SpdBatchNormOpts
  { spdBatchNormIters = 20
  , spdBatchNormTol = 1e-6
  }

-- | Riemannian batch norm → `(normalized, batch_mean)`.
spdBatchNorm :: Graph -> Node -> Node -> Float -> IO (Node, Node)
spdBatchNorm = spdBatchNormWith defSpdBatchNorm

-- | 'spdBatchNorm' with explicit optional parameters.
spdBatchNormWith :: SpdBatchNormOpts -> Graph -> Node -> Node -> Float -> IO (Node, Node)
spdBatchNormWith opts' self' x gamma eps =
  withH self' $ \a0 ->
  allocaOut $ \o0 ->
  allocaOut $ \o1 ->
  do
    checkRc P.=<< c_rlx_graph_spd_batch_norm a0 x gamma (P.realToFrac eps) (spdBatchNormIters opts') (P.realToFrac (spdBatchNormTol opts')) o0 o1
    r0 <- peekU32 o0
    r1 <- peekU32 o1
    P.pure (r0, r1)

-- | The transport step of SPD batch norm against a given `mean`.
spdBatchNormTransport :: Graph -> Node -> Node -> Node -> Float -> IO Node
spdBatchNormTransport self' x mean gamma eps =
  withH self' $ \a0 ->
  allocaOut $ \o0 ->
  do
    checkRc P.=<< c_rlx_graph_spd_batch_norm_transport a0 x mean gamma (P.realToFrac eps) o0
    peekU32 o0

