  allocaOut $ \o0 ->
  do
    checkRc P.=<< c_rlx_graph_spd_karcher_mean a0 x (spdKarcherMeanIters opts') (P.realToFrac (spdKarcherMeanTol opts')) (P.maybe none P.id (spdKarcherMeanWeights opts')) o0
    peekU32 o0

